"""Measured egg adaptations after reading ingredients and full methods together."""
import json,pathlib,sqlite3
root=pathlib.Path(__file__).parent
c=sqlite3.connect(root.parent.parent/'outputs/SavorShelf-Content-Repairs/grouped-work.sqlite3')
def original(id):return json.loads(c.execute('select record from recipes where id=?',(id,)).fetchone()[0])
byid={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
merges={'historical-9509445951d57e023b01f73d':'historical-b42799f5292cd308f900f0dd','historical-5e5e56697360bdb078665e3c':'historical-b42799f5292cd308f900f0dd','historical-785905f9b64f7f02909b7562':'historical-b42799f5292cd308f900f0dd','historical-dbc8eb3673490e0bcd3f5cb0':'historical-5f315b26af68c87c44e53e97','historical-bba91ca7e7d34c8b895459a6':'historical-22c5476af5485ba63e844d80'}
poachref='https://eggs.ca/eggs101/how-to-poach-an-egg-like-a-pro/'
bakeref='https://eggs.ca/recipes/shirred-eggs/'
safety='https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety'
def i(key,amount,unit,name,sub):return dict(key=key,amount=amount,unit=unit,name=name,substitution=sub)
def eggs(n):return i('eggs',n,'','large hen eggs','Use large pasteurized shell eggs for a soft-yolk option. Liquid egg substitute cannot retain this whole-egg shape.')
def water(n):return i('water',n,'ml','poaching water','Use drinking water; adjust depth to fit the pan. This water is drained, not consumed.')
def salt(n):return i('salt',n,'g','fine salt','Reduce or omit; exchange other salt by weight rather than spoon volume.')
def butter(n):return i('butter',n,'g','unsalted butter','Use the same weight of dairy-free butter alternative; check its salt content.')
def bread(n):return i('bread',n,'','bread slices, about 35 g each','Use similarly sized gluten-free bread; toasting time may differ.')
def vinegar(n):return i('vinegar',n,'ml','white wine vinegar','Use the same volume of distilled white vinegar, or omit for a milder flavor.')
def add(id,title,n,minutes,desc,items,steps,notes,ref=poachref,category='Breakfast'):
 s=original(id);r=dict(s['recipe']);r.update(title=title,description=desc,category=category,servings=n,yieldUnit='servings',minutes=minutes,totalMinutes=minutes,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T00:00:00Z',notes=notes+' Supplied quantities, yield and times are modern estimates, not recovered source facts. Cook ordinary eggs until both whites and yolks are firm; a soft-yolk option requires pasteurized shell eggs. Scale to whole eggs and cook in batches rather than extending the per-egg time. Not kitchen-tested.',source=s['recipe']['source']+' SavorShelf measured adaptation. Technique reference: '+ref+' Egg guidance: '+safety)
 r['sourceAliases']=[old for old,new in merges.items() if new==id]
 for old in r['sourceAliases']:r['source']+=' Equivalent source retained: '+original(old)['recipe']['source']
 byid[id]={'sourceId':id,'bodySha256':s['bodySha256'],'recipe':r}
poach='Crack {{eggs}} into separate cups. Slide gently into barely simmering water, keeping them apart; cook no more than four at a time. Check from 4 minutes and continue until whites and yolks are firm, usually 5–7 minutes. For pasteurized shell eggs only, 3–4 minutes gives a softer yolk. Lift with a slotted spoon and drain.'
add('historical-6a247ab8b8a68cac252cdd12','Poached Eggs on Anchovy Toast',6,25,'Poached eggs top crisp buttered toast spread with anchovy paste for a salty, savory breakfast.',[eggs(6),water(1500),bread(6),butter(30),salt(1),i('anchovy',12,'g','anchovy paste','Omit for plain toast, or use 12 g mashed capers for a fish-free variation with a different flavor.')],['Bring {{water}} to a gentle simmer in a wide saucepan, with enough depth to submerge the eggs.','Toast {{bread}}; spread with {{butter}} and then {{anchovy}}. Keep warm.',poach,'Top each toast with a drained egg and divide {{salt}} over the eggs. Serve immediately.'],'The six-egg/six-toast structure is retained; a normal saucepan replaces the hand-held dipper. Anchovy paste is the included source variation.')
add('historical-0d8cc30aa57193ec432070f0','Fried Bacon with Poached Eggs',2,25,'Pan-fried bacon is topped with drained poached eggs for a simple savory breakfast.',[i('bacon',150,'g','fresh sliced bacon','Use 150 g turkey bacon and follow its package cooking instructions; flavor and fat differ.'),eggs(2),water(1000)],['Put {{bacon}} in a cold frying pan. Cook over medium heat, turning regularly, until fully cooked according to its package and crisp to preference, usually 8–12 minutes. Drain on a warm plate.','Meanwhile bring {{water}} to a gentle simmer in a separate saucepan.',poach,'Divide bacon between two warm plates and top each with a drained egg. Serve immediately.'],'Use sound refrigerated bacon; the source instruction to trim deteriorated bacon is not retained.')
add('historical-b2d13dcc73a73d8b97f5c091','Huevos Escalfados en Crema (Eggs in Cream)',2,25,'Whole eggs bake gently with cream and butter in individual dishes for a rich, spoonable breakfast.',[eggs(2),butter(10),salt(1),i('cream',30,'ml','heavy cream','Use 30 ml whole milk for a thinner, less rich finish.')],['Heat the oven to 180°C (350°F). Grease two ovenproof 150–200 ml ramekins with {{butter|0.5}} and set on a baking tray.','Warm {{cream}} with the remaining {{butter|0.5}} until the butter melts; mix in {{salt}}.','Crack {{eggs}}, one into each ramekin. Divide the warm cream mixture around them.','Bake 12–18 minutes, checking from 12 minutes, and continue until whites and yolks are firm. Serve on plates beneath the hot ramekins.'],'Ovenproof ramekins and a measured oven temperature replace a covered plate over unspecified direct heat. Butter is divided between greasing and cream.',bakeref)
add('historical-d1864f576701d0c3954af9a7','Spinach with Hard-Boiled Eggs',3,30,'Tender spinach is drained, tossed with butter and topped with slices of hard-boiled egg.',[i('spinach',600,'g','fresh spinach, washed and tough stems removed','Use 300 g frozen leaf spinach, cooked according to its package and drained; this is a practical substitute, not a historical volume conversion.'),i('water',240,'ml','water for the spinach','Use drinking water; separate egg-boiling and cooling water is discarded.'),butter(14),eggs(3)],['Put {{eggs}} in one layer in a saucepan and cover with separate cold water by 2 cm. Bring to a boil, reduce to a gentle simmer and cook 10–12 minutes until yolks are firm. Cool under cold running water, peel and slice.','Bring {{water}} to a simmer in a large pan. Add {{spinach}} in batches, cover and cook 3–5 minutes, turning until all leaves are wilted and tender.','Drain thoroughly. Return spinach to the warm pan off the heat and toss with {{butter}}. Arrange on a dish and top with the sliced eggs.'],'The missing plain-spinach cross-reference is replaced with full steps. The 600 g amount is a modern batch choice, not a precise conversion of half a peck.',safety,'Sides')
add('historical-3cd9725ee236e6684da4a259','Tojás Ülepedve (Eggs with Sour Cream, Anchovies and Pickles)',2,30,'Eggs bake over sour cream with anchovy strips and tart cucumber pickle, retaining the source’s salty, tangy combination.',[eggs(4),butter(5),i('cream',30,'g','sour cream','Use 30 g full-fat plain Greek yogurt; it may separate slightly.'),i('anchovy',8,'g','drained anchovy fillets, sliced','Use 8 g chopped capers for a fish-free variation with a different flavor.'),i('pickle',60,'g','drained dill-pickled cucumber, sliced','Use the same weight of another unsweetened cucumber pickle.')],['Heat the oven to 180°C (350°F). Grease a shallow ovenproof dish about 18 cm across with {{butter}} and spread {{cream}} over its base.','Crack {{eggs}} individually into a cup, then slide into the dish without breaking the yolks. Arrange {{anchovy}} between them and {{pickle}} around the edge.','Bake 15–22 minutes, checking from 15 minutes, until whites and yolks are firm. Divide between two plates and serve hot.'],'The 12-egg source is reduced to four eggs. An oven replaces coals; drained anchovy fillets replace cleaned, soaked whole salt anchovies.',bakeref)
for id,title,n,w,sa,vi,depth in [('historical-b42799f5292cd308f900f0dd','Förlorade Ägg (Shallow-Poached Eggs on Fried Bread)',4,1000,3,2.5,'Use a wide pan with about 2 cm water depth.'),('historical-5f315b26af68c87c44e53e97','Förlorade Ägg (Six-Egg Pan Method)',6,1500,6,2.5,'Use a wide pan and cook the eggs in two batches.'),('historical-22c5476af5485ba63e844d80','Helförlorade Ägg (Deep-Poached Eggs)',4,1500,18,15,'Use a deep saucepan with headroom above the water.')]:
 items=[eggs(n),water(w),salt(sa),vinegar(vi)];steps=['Bring {{water}}, {{salt}} and {{vinegar}} to a boil, then lower to a barely moving simmer. '+depth,poach]
 desc='Whole eggs poach in gently simmering, acidulated water and are lifted out with their whites gathered around the yolks.'
 if id=='historical-b42799f5292cd308f900f0dd':
  items += [bread(4),butter(20)];steps+=['Melt {{butter}} in a separate frying pan over medium heat. Fry {{bread}} for 1–2 minutes per side until golden, in batches if needed.','Put a drained egg on each bread slice and serve hot.'];desc='Shallow-poached eggs are drained and served on bread fried in butter; a dry-toast variation is retained.'
 else:steps+=['Serve the drained eggs promptly on warm plates. Toast or sauce is a separate accompaniment.']
 add(id,title,n,25,desc,items,steps,'The distinct water/salt/vinegar formula is retained with modern batch amounts. Gentle simmering replaces vigorous boiling where specified. Cold rinsing and decorative trimming are omitted for immediate hot service.')
r=byid['historical-b42799f5292cd308f900f0dd']['recipe'];r['variants']=[{'id':'dry-toast','label':'On dry toast','ingredients':[x for x in r['ingredients'] if x['key']!='butter'],'steps':r['steps'][:2]+['Toast {{bread}} until crisp. Top each slice with a drained egg and serve hot.']}]
for old,new in merges.items():aliases[old]={'id':old,'canonicalId':new,'bodySha256':original(old)['bodySha256'],'reason':'Full ingredients and methods compared: repeated transcription of the same source formulation. Source credit is retained; fried bread and dry toast remain distinct serving variations where applicable.'}
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'content-overrides.json').write_text(json.dumps(list(byid.values()),ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps({'newAdaptations':8,'newMergedSources':5,'totalOverrides':len(byid),'totalAliases':len(aliases)}))
